import pypdf

reader = pypdf.PdfReader("/root/sc100-blank.pdf")
fields = reader.get_fields()

if fields:
    for field_name, value in fields.items():
        print(f"Field: {field_name}, Type: {value.get('/FT')}")
        if value.get('/FT') == '/Btn':
            print(f"  - Options: {value.get('/Opt')}")
            # Sometimes options are in kids or AP
            if '/AP' in value:
                print(f"  - Appearance (AP): {value['/AP'].keys()}")
                if '/N' in value['/AP']:
                     print(f"    - Normal Appearance (N): {value['/AP']['/N'].keys()}")
else:
    print("No fields found.")
